func TestDebugClient(t *testing.T) {
	t.Run("returns the same client pointer", func(t *testing.T) {
		c := &http.Client{}
		got := httpx.DebugClient(c)
		require.Same(t, c, got)
	})

	t.Run("sets the transport to a DebugTransport", func(t *testing.T) {
		c := &http.Client{}
		httpx.DebugClient(c)
		_, ok := c.Transport.(httpx.DebugTransport)
		require.True(t, ok)
	})

	t.Run("preserves a pre-existing transport as delegate", func(t *testing.T) {
		inner := &http.Client{}
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			_, _ = w.Write([]byte("inner"))
		}))
		t.Cleanup(srv.Close)

		c := httpx.DebugClient(inner)
		resp, err := c.Get(srv.URL)
		require.NoError(t, err)
		defer resp.Body.Close()
		require.Equal(t, http.StatusOK, resp.StatusCode)
	})

	t.Run("makes a request through the debug transport", func(t *testing.T) {
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			w.Header().Set("X-Test", "yes")
			_, _ = w.Write([]byte("hello"))
		}))
		t.Cleanup(srv.Close)

		c := httpx.DebugClient(&http.Client{})
		resp, err := c.Get(srv.URL)
		require.NoError(t, err)
		defer resp.Body.Close()
		require.Equal(t, http.StatusOK, resp.StatusCode)
		require.Equal(t, "yes", resp.Header.Get("X-Test"))
	})

	t.Run("handles a nil transport", func(t *testing.T) {
		c := &http.Client{Transport: nil}
		got := httpx.DebugClient(c)
		require.Same(t, c, got)
		_, ok := c.Transport.(httpx.DebugTransport)
		require.True(t, ok)
	})

	t.Run("handles a non-nil custom transport", func(t *testing.T) {
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			_, _ = w.Write([]byte("custom"))
		}))
		t.Cleanup(srv.Close)

		c := &http.Client{}
		httpx.DebugClient(c)
		resp, err := c.Get(srv.URL)
		require.NoError(t, err)
		defer resp.Body.Close()
		require.Equal(t, http.StatusOK, resp.StatusCode)
	})
}
